const $=s=>document.querySelector(s);
const tabs=['Overview','Emergency drugs','Anesthetic drugs','Fluid calculations','Respiratory','Preanesthetic checklist'];
const icons=['◫','✚','⚕','◉','≋','☑'];let page=0;let data={};let checked=new Set();
const cpr='https://onlinelibrary.wiley.com/doi/10.1111/vec.13391';
const fluidRef='https://www.aaha.org/resources/2024-aaha-fluid-therapy-guidelines-for-dogs-and-cats/section-4-fluid-therapy-and-anesthesia/';
const anesthesiaRef='https://www.aaha.org/resources/2020-aaha-anesthesia-and-monitoring-guidelines-for-dogs-and-cats/';
function kg(){const w=Number($('#weight').value);return Number.isFinite(w)&&w>0?w*($('#weightUnit').value==='lb'?0.45359237:1):NaN}
function positive(v){return Number.isFinite(Number(v))&&Number(v)>0}
function fmt(v){if(!Number.isFinite(v)||v<=0)return '—';if(v<.001)return v.toExponential(3);return Number(v.toPrecision(5)).toString()}
function field(id,label,value='',unit=''){if(!(id in data))data[id]=value;return `<label>${label}${unit?' · '+unit:''}<input data-key="${id}" type="number" min="0" step="any" value="${data[id]}" placeholder="Enter value"></label>`}
function result(id){return `<div class="result" id="${id}" aria-live="polite">—</div>`}
function source(url,title){return `<div class="ref">Reference: <a href="${url}" target="_blank" rel="noopener">${title} ↗</a></div>`}
function head(title,sub){return `<div class="sectionhead"><div><p class="eyebrow">02 / ${page===0?'YOUR TOOLKIT':'CLINICAL TOOLS'}</p><h2>${title}</h2><p>${sub}</p></div><span class="pill">${Number.isFinite(kg())?fmt(kg())+' KG':'PATIENT WEIGHT REQUIRED'}</span></div>`}
function nav(){ $('#nav').innerHTML=tabs.map((t,i)=>`<button data-page="${i}" class="${i===page?'active':''}">${icons[i]} &nbsp; ${t}</button>`).join('');$('#crumb').textContent=tabs[page]}
function drug(id,name,dose,unit,note,defaultConc=''){return `<article class="card"><span class="tag">${page===1?'RECOVER 2024 · IV / IO':'CLINICIAN-ENTERED REGIMEN'}</span><h3>${name}</h3><p>${note}</p><div class="formrow">${field(id+'Dose','Dose',dose,unit+'/kg')}${field(id+'Conc','Vial concentration',defaultConc,unit+'/mL')}</div>${result(id+'Result')}</article>`}
let activeDrugs=[];
function render(){nav();let h='';activeDrugs=[];
if(page===0){const desc=['RECOVER-based CPR doses, with patient-specific volumes.','Opioids, anxiolytics, induction agents, antibiotics & more.','Surgical fluid rates, bolus volumes, and pump rates.','Tidal volume, minute ventilation, and reservoir sizing.','A deliberate pause before induction.'];h=head('Prepared for every phase.','Choose a tool to get started. Your patient weight follows you.')+`<div class="grid">`+desc.map((d,i)=>`<article tabindex="0" role="button" aria-label="Open ${tabs[i+1]}" data-page="${i+1}" class="card tool ${i===0?'emergency':''}"><div class="icon">${icons[i+1]}</div><h3>${tabs[i+1]}</h3><p>${d}</p><span class="tag">${i===0?'RECOVER 2024':i===4?'BEFORE YOU BEGIN':'PATIENT-BASED CALCULATOR'}</span><span class="arrow">↗</span></article>`).join('')+`<article class="card"><span class="tag">BUILT AROUND YOUR PATIENT</span><h3>Small details.<br>Safer calculations.</h3><p>Visible units. Adjustable concentrations. Transparent formulas.</p></article></div><div class="bottom"><article class="card"><h3>A clearer path to preparation</h3><div class="steps"><span><b>1</b> Enter weight</span><span><b>2</b> Confirm inputs</span><span><b>3</b> Review together</span></div></article><article class="card"><span class="tag">REFERENCE LIBRARY</span><h3>Grounded in guidelines.</h3>${source(cpr,'RECOVER CPR 2024')}${source(fluidRef,'AAHA fluids 2024')}</article></div>`}
if(page===1){const cat=$('#species').value==='cat';activeDrugs=[['epi','Epinephrine',.01,'mg','Nonshockable arrest: every 3–5 min. For shockable arrest, only after first shock; vasopressin preferred if available.'],['vaso','Vasopressin',.8,'U','Alternative to epinephrine, every 3–5 min; refractory shockable arrest after the first shock.'],['atro','Atropine',.04,'mg','Nonshockable arrest, particularly suspected high vagal tone. Give once, early; do not repeat.'],cat?['amio','Amiodarone',5,'mg','Cats: refractory VF / pulseless VT after first unsuccessful shock. Give over 2–4 min.']:['lido','Lidocaine',2,'mg','Dogs: refractory VF / pulseless VT after first unsuccessful shock. Give over 2–4 min.'],['nal','Naloxone',.04,'mg','Recent opioid administration: after BLS and priority ALS interventions have begun.']];h=head('Emergency drug calculator','Adult dogs and cats · CPR cognitive aid')+`<div class="alert">Follow the full CPR algorithm. High-dose epinephrine is not recommended. Routine fluid boluses are not recommended in euvolemic arrest. Enter the actual vial concentration; dose fields are editable.</div><div class="grid">`+activeDrugs.map(d=>drug(...d)).join('')+'</div>'+source(cpr,'RECOVER 2024 treatment recommendations · Table 2 and ALS recommendations')}
if(page===2){const groups={'Opioids':['Methadone','Fentanyl','Buprenorphine','Hydromorphone'],'Anxiolytics & sedatives':['Midazolam','Diazepam','Dexmedetomidine','Acepromazine'],'GI & antiemetics':['Maropitant','Ondansetron','Metoclopramide'],'Induction agents':['Propofol','Alfaxalone','Ketamine','Etomidate'],'Perioperative antibiotics':['Cefazolin','Ampicillin'],'Reversal agents':['Naloxone','Atipamezole','Flumazenil']};h=head('Anesthetic drug calculator','Select a category and enter the prescribed dose and formulation.')+`<div class="alert">Dose selection, route, timing, contraindications, and antibiotic indication require a veterinarian-approved protocol. Blank doses are intentional. Calculations do not validate a regimen.</div><label>Drug category<select id="category">${Object.keys(groups).map(k=>`<option ${data.category===k?'selected':''}>${k}</option>`).join('')}</select></label><div class="grid category">`;const group=data.category||'Opioids';groups[group].forEach((name,i)=>{const id='med'+name.replaceAll(' ','');const unit=name==='Fentanyl'||name==='Dexmedetomidine'?'µg':'mg';activeDrugs.push([id,name,'',unit]);h+=drug(id,name,'',unit,'Prescribed dose × body weight ÷ concentration. Confirm route and patient suitability.');});h+='</div>'+source(anesthesiaRef,'AAHA anesthesia and monitoring guidelines')}
if(page===3){h=head('Fluid calculations','Balanced isotonic crystalloid calculations · individualize to perfusion and fluid tolerance.')+`<div class="alert">AAHA 2024 initial rates for normal cardiac and renal function: dogs 5 mL/kg/hr; cats 3–5 mL/kg/hr. Hypotension does not always respond to fluids. Bolus dose and duration must be prescribed.</div><div class="grid"><article class="card"><span class="tag">SURGICAL / INTRAOPERATIVE</span><h3>Continuous fluid rate</h3>${field('rate','Prescribed rate', $('#species').value==='cat'?3:5,'mL/kg/hr')}${field('hours','Planned duration',1,'hr')}${result('rateResult')}</article><article class="card"><span class="tag">INTRAOPERATIVE</span><h3>Fluid bolus</h3>${field('bolus','Prescribed bolus','','mL/kg')}${field('minutes','Delivery duration','','min')}${result('bolusResult')}</article><article class="card"><span class="tag">GRAVITY INFUSION</span><h3>Drip calculation</h3>${field('drip','Giving-set factor','','drops/mL')}${result('dripResult')}<p>Uses the continuous fluid rate. Verify the giving-set label.</p></article></div>`+source(fluidRef,'AAHA 2024 · Fluid therapy and anesthesia')}
if(page===4){h=head('Respiratory calculations','Planning estimates · confirm against circuit specifications and measured ventilation.')+`<div class="alert">Tidal volume and respiratory rate are clinician-entered targets, not ventilator prescriptions. Reservoir volume is calculated as tidal volume × selected multiplier; confirm actual circuit and manufacturer requirements.</div><div class="grid"><article class="card"><h3>Tidal & minute volume</h3>${field('tv','Selected tidal volume','','mL/kg')}${field('rr','Selected respiratory rate','','breaths/min')}${result('tvResult')}</article><article class="card"><h3>Reservoir bag</h3>${field('mult','Reservoir multiplier',5,'× tidal volume')}${result('bagResult')}<p>Rounds up to 0.5, 1, 2, 3, 4, 5, or 6 L. Above 6 L, select suitable equipment manually.</p></article><article class="card"><h3>Apparatus dead space</h3>${result('deadResult')}<p>AAHA suggests minimizing dead space to ≤2–3 mL/kg and ≤20% of tidal volume. The stricter limit is shown when tidal volume is entered.</p></article></div>`+source('https://onlinelibrary.wiley.com/doi/10.1111/avj.12762','2018 Australian Veterinary Journal anesthesia guidelines · reservoir multiplier')+source(anesthesiaRef,'AAHA 2020 · equipment and dead space')}
if(page===5){const lists={'Patient & plan':['Confirm patient, species, weight, and procedure','Review examination, history, current medications, and allergies','Review indicated laboratory results and assign ASA status','Confirm individualized fasting, hydration, and consent','Approve analgesia, anesthetic doses, routes, and recovery plan'],'Equipment & team':['Verify oxygen supply, backup supply, and scavenging','Leak-test machine and circuit per manufacturer instructions','Check APL / pop-off valve, reservoir bag, and circuit size','Prepare ETT sizes, laryngoscope, cuff check, and suction','Verify IV access, labeled syringes, concentrations, and fluids','Check ECG, SpO₂, blood pressure, capnography, and temperature','Prepare warming and emergency drugs; assign monitoring roles'],'Before induction':['Perform team time-out and confirm procedure/site','Confirm preoxygenation plan and emergency readiness','Assign recovery observer and monitoring / handoff plan']};let n=0;h=head('Preanesthetic checklist','A preparation aid adapted from AAHA guidance; supplement with your local protocol.')+`<article class="card"><b id="count"></b><progress id="progress" max="15"></progress><button class="outline" id="resetChecks">Reset checklist</button></article><div class="grid category">`;for(const [title,items]of Object.entries(lists)){h+=`<article class="card checks"><h3>${title}</h3>`+items.map(t=>{const i=n++;return `<label><input type="checkbox" data-check="${i}" ${checked.has(i)?'checked':''}>${t}</label>`}).join('')+'</article>'}h+='</div>'+source(anesthesiaRef,'AAHA 2020 anesthesia and monitoring guidelines')}
$('#content').innerHTML=h;calculate()}
function calculate(){const w=kg();$('#status').innerHTML=Number.isFinite(w)?fmt(w)+' kg<br><small>Calculation weight</small>':'Enter weight<br><small>to calculate</small>';const show=(id,html)=>{const e=$('#'+id);if(e)e.innerHTML=html};const number=id=>positive(data[id])?Number(data[id]):NaN;
for(const [id,name,dose,unit]of activeDrugs){const total=w*number(id+'Dose'),v=total/number(id+'Conc');show(id+'Result',`${fmt(v)} <span style="font-size:14px">mL</span><small>Total dose: ${fmt(total)} ${unit} · ${fmt(w)} kg × ${data[id+'Dose']||'—'} ${unit}/kg ÷ ${data[id+'Conc']||'—'} ${unit}/mL</small>${v>0&&v<.01?'<small>Very small volume: verify dilution and measurement accuracy.</small>':''}`)}
const rate=w*number('rate'),duration=number('hours');show('rateResult',`${fmt(rate)} mL/hr<small>Total over ${fmt(duration)} hr: ${fmt(rate*duration)} mL · weight × rate × duration</small>${number('rate')*duration>20?'<small>Exceeds 20 mL/kg per episode: reassess volume status and rate.</small>':''}`);const bol=w*number('bolus');show('bolusResult',`${fmt(bol)} mL<small>Pump rate: ${fmt(bol*60/number('minutes'))} mL/hr · volume × 60 ÷ minutes</small>`);show('dripResult',`${fmt(rate*number('drip')/60)} drops/min<small>mL/hr × giving-set factor ÷ 60</small>`);const tv=w*number('tv');show('tvResult',`${fmt(tv)} mL<small>Minute volume: ${fmt(tv*number('rr')/1000)} L/min · tidal volume × respiratory rate ÷ 1000</small>`);const bag=tv*number('mult')/1000;const size=[.5,1,2,3,4,5,6].find(x=>x>=bag);show('bagResult',`${fmt(bag)} L minimum<small>Available-size estimate: ${positive(bag)?size?size+' L':'Above listed sizes':'—'}</small>`);show('deadResult',`${fmt(Number.isFinite(tv)?Math.min(w*2,tv*.2):w*2)} mL<small>Conservative planning limit: min(2 mL/kg, 20% of selected tidal volume)</small>`);if($('#count')){$('#count').textContent=checked.size+' / 15 preparation items complete';$('#progress').value=checked.size}}
document.addEventListener('click',e=>{const target=e.target.closest('[data-page]');if(target){page=Number(target.dataset.page);render()}if(e.target.id==='resetChecks'){checked.clear();render()}});
document.addEventListener('keydown',e=>{if(e.target.matches('.tool')&&(e.key==='Enter'||e.key===' ')){e.preventDefault();page=Number(e.target.dataset.page);render()}});
document.addEventListener('input',e=>{if(e.target.dataset.key){data[e.target.dataset.key]=e.target.value;calculate()}if(e.target.id==='weight')calculate()});
document.addEventListener('change',e=>{if(e.target.id==='category'){data.category=e.target.value;render()}if(e.target.id==='species'){delete data.rate;render()}if(e.target.id==='weightUnit')calculate();if(e.target.dataset.check!==undefined){const i=Number(e.target.dataset.check);e.target.checked?checked.add(i):checked.delete(i);calculate()}});
$('#print').onclick=()=>window.print();render();
